// Bounded: N workers share one cursor over the list
Future<List<R>> mapPooled<T, R>(
  Iterable<T> items,
  Future<R> Function(T) task, {
  int concurrency = 6,
}) async {
  final queue = items.toList();
  final results = List<R?>.filled(queue.length, null);
  var next = 0;

  Future<void> worker() async {
    while (true) {
      final i = next++;              // single isolate: no lock needed here
      if (i >= queue.length) return;
      results[i] = await task(queue[i]);
    }
  }

  await Future.wait([
    for (var i = 0; i < concurrency; i++) worker(),
  ]);
  return results.cast<R>();
}

