// Loses the origin: a new throw builds a new trace
try {
  await repo.save(order);
} catch (e) {
  throw SaveFailed('$e');                  // trace now starts on this line
}

// Keeps it: report the pair, wrap with the original trace
try {
  await repo.save(order);
} catch (e, st) {
  log.error('save failed', e, st);
  Error.throwWithStackTrace(SaveFailed(e), st);
}

// rethrow, never `throw e`
try {
  await repo.save(order);
} catch (e) {
  metrics.increment('save.error');
  rethrow;                                 // `throw e` would reset the trace
}

