// The real-world shape
class Warmup {
  late final Future<Config> _config = api.loadConfig();   // starts, and fails, here

  Future<void> run() async {
    await Future<void>.delayed(const Duration(seconds: 1));
    try {
      apply(await _config);     // too late: nobody was listening when it failed
    } catch (e) {
      showBanner('$e');
    }
  }
}

// Fix: mark it handled in the same turn it is created
late final Future<Config> _config = api.loadConfig()..ignore();

// Fix: attach a real handler now, keep the future to await later
Future<Config> start() {
  final f = api.loadConfig();
  unawaited(f.catchError((Object e, StackTrace st) {
    crash.recordError(e, st);
    return Config.fallback;     // the report is handled; f still carries the error
  }));
  return f;
}

